create or replace function public.gymflow_member_login(p_code text) returns jsonb language plpgsql security definer set search_path=public as $$ declare m jsonb; g jsonb; begin if p_code !~ '^[0-9]{6}$' then raise exception 'Invalid access code.'; end if; select payload into m from public.gymflow_records where record_type='members' and payload->>'code'=p_code limit 1; if m is null then raise exception 'Member access code not found.'; end if; if coalesce(m->>'status','')='Blocked' or ((m->>'expiry')::date < (now() at time zone 'Asia/Kolkata')::date) then raise exception 'Membership is inactive or expired.'; end if; select payload into g from public.gymflow_records where record_type='gyms' and gym_id=m->>'gymId' limit 1; return jsonb_build_object('member',m,'gym',coalesce(g,'{}'::jsonb),'plans',coalesce((select jsonb_agg(payload) from public.gymflow_records where gym_id=m->>'gymId' and record_type='plans'),'[]'::jsonb),'workouts',coalesce((select jsonb_agg(payload) from public.gymflow_records where gym_id=m->>'gymId' and record_type='workouts'),'[]'::jsonb),'diets',coalesce((select jsonb_agg(payload) from public.gymflow_records where gym_id=m->>'gymId' and record_type='diets'),'[]'::jsonb),'attendance',coalesce((select jsonb_agg(payload order by payload->>'date') from public.gymflow_records where gym_id=m->>'gymId' and record_type='attendance' and payload->>'memberId'=m->>'id'),'[]'::jsonb)); end; $$;
create or replace function public.gymflow_member_update(p_code text,p_member jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare existing jsonb; begin select payload into existing from public.gymflow_records where record_type='members' and payload->>'code'=p_code limit 1; if existing is null then raise exception 'Member not found.'; end if; if p_member->>'id' <> existing->>'id' then raise exception 'Invalid member.'; end if; update public.gymflow_records set payload=p_member,updated_at=now() where id=existing->>'id' and record_type='members'; return p_member; end; $$;
create or replace function public.gymflow_member_attendance(p_code text,p_attendance jsonb) returns jsonb language plpgsql security definer set search_path=public as $$ declare m jsonb; gym text; mid text; d text; begin select payload,gym_id into m,gym from public.gymflow_records where record_type='members' and payload->>'code'=p_code limit 1; if m is null then raise exception 'Member not found.'; end if; mid:=m->>'id'; d:=p_attendance->>'date'; if d <> to_char(now() at time zone 'Asia/Kolkata','YYYY-MM-DD') then raise exception 'Attendance QR is only valid for today.'; end if; if exists(select 1 from public.gymflow_records where record_type='attendance' and gym_id=gym and payload->>'memberId'=mid and payload->>'date'=d) then return jsonb_build_object('ok',true,'already',true); end if; insert into public.gymflow_records(id,gym_id,record_type,payload) values (p_attendance->>'id',gym,'attendance',p_attendance); m:=jsonb_set(m,'{attendance}',to_jsonb(coalesce((m->>'attendance')::int,0)+1),true); update public.gymflow_records set payload=m,updated_at=now() where id=mid and record_type='members'; return jsonb_build_object('ok',true,'attendance',m->>'attendance'); end; $$;
grant execute on function public.gymflow_member_login(text) to anon,authenticated;
grant execute on function public.gymflow_member_update(text,jsonb) to anon,authenticated;
grant execute on function public.gymflow_member_attendance(text,jsonb) to anon,authenticated;
